// ---------------------------------------------------------------------------
// scripts/gen-deploy.mjs — generates deploy/ hosting configs from the canonical
// header spec (scripts/security-headers.mjs). One source of truth; verify-deploy
// independently re-parses the generated files.
//   node scripts/gen-deploy.mjs
// ---------------------------------------------------------------------------

import { mkdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { CANONICAL_HEADERS } from "./security-headers.mjs";

const root = fileURLToPath(new URL("..", import.meta.url));
mkdirSync(root + "deploy", { recursive: true });
const write = (rel, text) => {
  writeFileSync(root + rel, text);
  console.log("generated", rel);
};

const GENERATED = "# GENERATED by scripts/gen-deploy.mjs from scripts/security-headers.mjs — do not edit by hand; regenerate instead.";

// ---- _headers (Netlify & Cloudflare Pages both read this format) ----------
{
  let out = GENERATED + "\n\n# Serve the app document with the full lockdown header set.\n\n";
  for (const path of ["/", "/index.html"]) {
    out += path + "\n";
    for (const h of CANONICAL_HEADERS) out += `  ${h.name}: ${h.value}\n`;
    out += "\n";
  }
  write("deploy/_headers", out);
}

// ---- vercel.json -----------------------------------------------------------
{
  const conf = {
    _note: "Generated by scripts/gen-deploy.mjs — do not edit by hand.",
    headers: [
      {
        source: "/(.*)",
        headers: CANONICAL_HEADERS.map((h) => ({ key: h.name, value: h.value })),
      },
    ],
  };
  write("deploy/vercel.json", JSON.stringify(conf, null, 2) + "\n");
}

// ---- .htaccess (Apache, Apache 2.4+, mod_headers + mod_rewrite) -----------
{
  let out = GENERATED + "\n\n";
  out += `# Apache config for a public I Ching host. Place alongside dist/index.html
# (with AllowOverride enabled) or inline into the <VirtualHost>.

<IfModule mod_headers.c>
  # The app is a single self-contained document: apply to every response.
`;
  for (const h of CANONICAL_HEADERS) {
    if (h.name === "Strict-Transport-Security") {
      out += `  # HSTS only on HTTPS responses (env set by the rewrite below).\n  Header always set ${h.name} "${h.value}" env=HTTPS\n`;
    } else {
      out += `  Header always set ${h.name} "${h.value}"\n`;
    }
  }
  out += `</IfModule>

<IfModule mod_rewrite.c>
  RewriteEngine On
  # B-16: plain HTTP must 308-redirect to HTTPS; nothing is ever served plaintext.
  RewriteCond %{HTTPS} !=on
  RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [R=308,L]
</IfModule>

# No directory listings, no server tokens leaking implementation details.
Options -Indexes
ServerSignature Off

# NOTE: the app sets no cookies. If a session layer is ever added, cookies must
# carry Secure + HttpOnly + SameSite=Lax (enforce at the proxy if possible).
`;
  write("deploy/.htaccess", out);
}

// ---- nginx.conf.example ----------------------------------------------------
{
  let out = GENERATED + "\n\n";
  out += `# nginx config for a public I Ching host (nginx ≥ 1.19).
# Set server_name and the two certificate paths, then include this in http{}.

# B-16: plain HTTP is a 308 redirect to HTTPS — nothing is ever served plaintext.
server {
    listen 80;
    listen [::]:80;
    server_name iching.example.org;
    return 308 https://$host$request_uri;
}

server {
    listen 443 ssl;
    listen [::]:443 ssl http2;
    server_name iching.example.org;

    ssl_certificate     /etc/letsencrypt/live/iching.example.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/iching.example.org/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:SSL:1m;
    ssl_session_timeout 1d;

    root /var/www/iching;                       # contains only index.html
    index index.html;

    # B-15: full lockdown header set (generated from the canonical spec).
`;
  for (const h of CANONICAL_HEADERS) {
    out += `    add_header ${h.name} "${h.value}" always;\n`;
  }
  out += `
    # NOTE: the app sets no cookies. If a session layer is ever added, cookies
    # must carry Secure + HttpOnly + SameSite=Lax.

    # Serve only the artifact; everything else 404s (no path traversal targets,
    # no server-side execution surface of any kind).
    location / {
        try_files $uri /index.html =404;
    }
    location ~ /\. { deny all; }

    server_tokens off;
}
`;
  write("deploy/nginx.conf.example", out);
}

console.log("Deploy configs generated from the canonical header spec.");
